// Expand palette rows to truecolor pixel maps once at module load.
export const FRAMES: Record<Skin, Record<AgentStatus, PixelFrame[]>> =
  Object.fromEntries(
    Object.entries(FRAME_ROWS).map(([skin, states]) => [
      skin,
      Object.fromEntries(
        Object.entries(states).map(([state, frames]) => [
          state,
          frames.map((rows) =>
            rows.map((row) => [...row].map((ch) => PALETTES[skin as Skin][ch] ?? null)),
          ),
        ]),
      ),
    ]),
  ) as Record<Skin, Record<AgentStatus, PixelFrame[]>>
